impl std::fmt::Display for TraversalGTypeContext<'_> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let chain: Vec<String> = self.__invocation_states.iter().map(|state| state.to_string()).collect();
        write!(f, "[{}]", chain.join(" "))
    }
}

